export function buildSpecPrompt(prdContent: string, featureDescription: string, qa: { question: string; answer: string }[]): string { const qaText = qa.map(q => `Q: ${q.question}
A: ${q.answer}`).join('

'); return `You are a software architect. Generate a feature spec and task list.

## Existing PRD
${prdContent}

## New Feature
${featureDescription}

## Clarifications
${qaText}

## Output Format
Output ONLY valid JSON with this exact structure:
${JSON.stringify(EXAMPLE_OUTPUT, null, 2)}

Generate the spec and tasks now:` }

const EXAMPLE_OUTPUT = { spec: '## Feature Name

**User story**: As a user...
**Acceptance criteria**: ...', tasks: [{ title: 'Example task', description: 'What to implement', category: 'functional', passes: false, passCondition: 'Verify condition' }] }
